window.UGO_IMG={"accovacciato": "data:image/png;base64,", "aterra": "data:image/png;base64,", "burro": "data:image/png;base64,", "calcio": "data:image/png;base64,", "camminata1": "data:image/png;base64,", "camminata2": "data:image/png;base64,", "caricapugno": "data:image/png;base64,", "colpito": "data:image/png;base64,", "colpitobasso": "data:image/png;base64,", "entrata": "data:image/png;base64,", "fischio": "data:image/png;base64,", "formaggio": "data:image/png;base64,", "formaggio2": "data:image/png;base64,", "formaggio3": "data:image/png;base64,", "freccia": "data:image/png;base64,", "guardia": "data:image/png;base64,", "ko": "data:image/png;base64,", "lancio": "data:image/png;base64,", "moneta": "data:image/png;base64,", "montante": "data:image/png;base64,", "parata": "data:image/png;base64,", "presa": "data:image/png;base64,", "provocazione": "data:image/png;base64,", "pugno": "data:image/png;base64,", "rialzo": "data:image/png;base64,", "ritratto": "data:image/png;base64,", "salto": "data:image/png;base64,", "sconfitta": "data:image/png;base64,", "sgambetto": "data:image/png;base64,", "stordito": "data:image/png;base64,", "super1": "data:image/png;base64,", "tifo": "data:image/png;base64,", "vittoria": "data:image/png;base64,", "vittoria2": "data:image/png;base64,"};window.UGO_SCR={"BURRO": "data:image/png;base64,", "CHARGE": "data:image/png;base64,", "CROLLO": "data:image/png;base64,", "FROMAGE": "data:image/png;base64,", "MONTE_BIANCO": "data:image/png;base64,", "SPREAD": "data:image/png;base64,", "VIVE_LA_FRANCE": "data:image/png;base64,"};window.UGO_SRC="\nQUOTES.ugo={intro:[\"Vive la France!\",\"Il Monte Bianco \u00e8 francese.\",\"Investo nella tua sconfitta.\",\"Bonjour. Anzi: au revoir.\"],win:[\"VIVE LA FRANCE!\",\"RIPRENDIAMOCI IL MONTE BIANCO!\",\"Spread chiuso. Hai perso.\",\"Formaggio francese, vittoria francese.\"],lose:[\"Sacrebleu...\",\"Mon Dieu... il Monte Bianco...\",\"Il mercato era contro di me.\"]};\nCOUPLE.ugo=COUPLE.ugo||{}; COUPLE.ugo.stefano={intro:[\"SDB... saresti un buon francese.\"],win:[\"Saresti un ottimo francese. Sconfitto, ma ottimo.\"],lose:[\"Lo dicevo: un buon francese.\"]};\nCOUPLE.stefano=COUPLE.stefano||{}; COUPLE.stefano.ugo={intro:[\"Ugo, il Monte Bianco \u00e8 italiano. Agli atti.\"],win:[\"Il Monte Bianco resta dov'\u00e8.\"],lose:[\"D'accordo, il formaggio \u00e8 vostro. Il Monte no.\"]};\nCOUPLE.ugo.allibrator={intro:[\"Allibrator, a quanto mi dai?\"],win:[\"Quota rispettata. Vive la France.\"],lose:[\"Il banco vince sempre... sacrebleu.\"]};\nCOUPLE.allibrator=COUPLE.allibrator||{}; COUPLE.allibrator.ugo={intro:[\"Ugo vincente? Te lo pago uno e uno.\"],win:[\"Schedina chiusa, Napoleone.\"],lose:[\"Quota sbagliata. Rimborso.\"]};\nCOUPLE.ugo.ciarli={intro:[\"Ciarli! Il Benacum \u00e8 quasi francese, sai?\"],win:[\"Il lago resta tuo. Il Monte Bianco no.\"],lose:[\"Oh tzi... in francese non si dice.\"]};\nCOUPLE.ciarli=COUPLE.ciarli||{}; COUPLE.ciarli.ugo={intro:[\"PANZONE! Pardon, panzon!\"],win:[\"OH TZI! Vive l'Italie!\"],lose:[\"Ugo... offri tu lo champagne.\"]};\nif(SPRITES.ugo){ const N=SPRITES.ugo; N.guardia2=N.guardia; N.paratabassa=N.accovacciato; N.lancio2=N.lancio; N.caricacalcio=N.caricapugno; N.sguardo=N.provocazione; N.turbo=N.pugno; N.sfondamento=N.pugno; N.stordita=N.stordito; N.super2=N.super1; N.esulta1=N.vittoria; N.esulta2=N.tifo; N.esulta3=N.vittoria; N.volo=N.ko; N.svenuto0=N.aterra; N.vittoria3=N.vittoria2; }\n/* UGO1 - base: distanza \"Moneta d'oro\" (SPREAD!); speciale \"Crollo in Borsa\" (freccia rossa dall'alto, CROLLO!); montante \"Rialzo\";\n   super \"Onda di burro\" (attraversa lo schermo, alta: quasi impossibile da saltare, BURRO!).\n   Napoleone: distanza \"Camembert\"; speciale \"Pioggia di formaggi\" (tre formaggi dall'alto, FROMAGE!); super \"Carica del dragone\" (a cavallo con la bandiera, CHARGE!). */\nfunction ugoImg(n){ const D=window.UGO_IMG||{}, c=SPRITES.__uImg=SPRITES.__uImg||{}; if(!D[n]) return null; if(!c[n]){ const i=new Image(); i.src=D[n]; c[n]=i; } return c[n].complete&&c[n].width?c[n]:null; }\ntry{ setTimeout(()=>['moneta','freccia','burro','formaggio','formaggio2','formaggio3'].forEach(ugoImg),0); }catch(e){}\nconst UGSU={dmgW:16,altoW:170,velW:17,dmgS:10,dmgF:[3,3,5],rngS:80,dmgC:18,velC:13};\nfunction drawUgoProj(p){ const im=ugoImg(p.kind==='formaggio'?'formaggio':'moneta'); if(!im) return false; const s=p.kind==='formaggio'?0.62:0.5; ctx.save(); ctx.translate(p.x,p.y); ctx.rotate((p.x/(p.kind==='formaggio'?30:14))*(p.vx<0?-1:1)); ctx.imageSmoothingEnabled=false; ctx.drawImage(im,-im.width*s/2,-im.height*s/2,im.width*s,im.height*s); ctx.restore(); return true; }\nfunction ugoCrollo(f){ const o=G.f1===f?G.f2:G.f1; if(f.usb||(f._usbT&&G.frame-f._usbT<200)){ floatText('...',f.x,f.y-240,f.def.accent,16,30,'balloon'); return; }\n  f._usbT=G.frame; const ev=f.def.lv>=2; f.usb={t:0,ev:ev?1:0,tgt:o,hx:o?o.x:f.x+(f.facing||1)*220,n:0,drops:[]};\n  floatText(ev?'Fromage!':'Vendete! Vendete!',f.x,f.y-250,f.def.accent,17,46,'balloon'); try{ tone('triangle',ev?520:880,ev?260:110,.5,.07); }catch(e){} }\nfunction stepUgo(f,o){ const t=o||null; const U=f.usb;\n  if(U){ U.t++; const tg=t||U.tgt; if(tg&&U.t<22) U.hx+=Math.max(-5,Math.min(5,tg.x-U.hx));\n    if(!U.ev){ if(U.t===22) U.drops.push({x:U.hx,t0:22,im:'freccia',d:UGSU.dmgS,last:1});\n    } else { [22,34,46].forEach((tt,i)=>{ if(U.t===tt) U.drops.push({x:U.hx+(i===1?-40:i===2?40:0),t0:tt,im:i===0?'formaggio2':(i===1?'formaggio3':'formaggio'),d:UGSU.dmgF[i],last:i===2}); }); }\n    for(const D of U.drops){ const k=U.t-D.t0; if(k===14&&!D.done){ D.done=1; G.shake=Math.max(G.shake||0,D.last?10:5); try{ tone('square',D.last?90:140,50,.25,.07); }catch(e){}\n        if(tg&&tg.state!=='ko'&&Math.abs(tg.x-D.x)<UGSU.rngS){ hit(f,tg,D.d,D.last?12:4,D.last?36:18,{sup:true,heavy:D.last,launch:D.last,dirx:tg.x>=f.x?1:-1,y:tg.y-150}); if(tg.state==='hit'&&D.last) floatText(U.ev?'FROMAGE!':'CROLLO!',tg.x,tg.y-230,'#ffd21a',28,60); } } }\n    if(U.t>(U.ev?80:56)) f.usb=null; }\n  const M=f.uw; if(!M) return; M.t++; const tw=t||M.tgt; if(M.t<12) return; M.cx+=M.dir*UGSU.velW; if(M.t%3===0) G.shake=Math.max(G.shake||0,4);\n  if(tw&&!M.hit&&tw.state!=='ko'&&Math.abs(tw.x-M.cx)<110){ M.hit=1; if(tw.y>GROUND-UGSU.altoW){ G.shake=Math.max(G.shake,16); hit(f,tw,UGSU.dmgW,16,46,{sup:true,low:true,heavy:true,launch:true,dirx:M.dir,y:tw.y-80}); if(tw.state==='hit') floatText('BURRO!',tw.x,tw.y-230,'#ffe27a',30,60); } }\n  if(M.dir>0?M.cx>W+600:M.cx<-600) f.uw=null; }\nfunction callUgo(f,o){ if(f.def.lv>=2&&ugoCavOk(f)){ floatText('CHARGE!',f.x,f.y-270,'#2a5bd8',26,60); floatText('Vive l\\'Empereur!',f.x,f.y-230,f.def.accent,16,46,'balloon'); try{ tone('sawtooth',196,392,.5,.08); }catch(e){} return; }\n  const dir=f.facing||1; f.uw={t:0,dir:dir,cx:f.x-dir*520,tgt:o,hit:0}; floatText(rnd()<.5?'RIPRENDIAMOCI IL MONTE BIANCO!':'Vive la France!',f.x,f.y-250,f.def.accent,16,50,'balloon'); try{ tone('triangle',220,90,.8,.09); }catch(e){} }\nfunction ugoCarica(f,o,a,m,fwd){ /*UGOCAR1: carica del dragone, sul modello della giostra di Socciaman*/\n  if(a.f<m.s){ f.vx=0; return; }\n  if(a.f===m.s){ f.ucar={hit:0,fwd}; G.excite=1; SFX.swing&&SFX.swing(); G.shake=Math.max(G.shake,5); }\n  const Q=f.ucar||(f.ucar={hit:0,fwd});\n  if(Q.hit>0){ Q.hit++; f.vx=fwd*2; return; }\n  f.vx=fwd*UGSU.velC;\n  if(a.f%2===0) for(let k=0;k<2;k++) FX.push({x:f.x-fwd*(40+rnd()*60),y:f.y-6-rnd()*14,vx:-fwd*(1+rnd()*2),vy:-1-rnd()*2,life:18,c:rnd()<.5?'#c8b49a':'#efe4d2'});\n  if(o&&!['ko','down'].includes(o.state)){ const dist=(o.x-f.x)*fwd;\n    if(dist>-10&&dist<150&&o.y>f.y-90){ hit(f,o,UGSU.dmgC,14,40,{heavy:true,launch:true,dirx:fwd,y:o.y-130}); Q.hit=1;\n      if(o.state==='hit'){ floatText('IL MONTE BIANCO \u00c8 FRANCESE!',o.x,o.y-215,'#2a5bd8',26,60); G.shake=Math.max(G.shake,12); for(let k=0;k<14;k++) FX.push({x:o.x-fwd*20,y:o.y-130+(rnd()-.5)*40,vx:fwd*(1+rnd()*5)+(rnd()-.5)*4,vy:-1-rnd()*5,life:22,c:k%3===0?'#ffffff':(k%2?'#d8262e':'#1d3c9a')}); } } } }\nfunction ugoCavOk(f){ try{ const S=rosaSP(f); return !!(f.def.lv>=2&&S&&S.cavallo1&&S.cavallo1.complete&&S.cavallo1.width); }catch(e){ return false; } }\nfunction drawUgo(F){ if(!F||!F.def||F.def.spriteKey!=='ugo') return; ctx.save(); ctx.imageSmoothingEnabled=false;\n  const U=F.usb; if(U){ for(const D of U.drops){ const k=U.t-D.t0; const im=ugoImg(D.im); if(!im) continue;\n      if(k<14){ const y=-120+(GROUND-40+120)*(k/14)*(k/14); const s=D.im==='freccia'?1.0:0.9; ctx.save(); ctx.translate(D.x,y); if(D.im!=='freccia') ctx.rotate(k*0.3); ctx.drawImage(im,-im.width*s/2,-im.height*s/2,im.width*s,im.height*s); ctx.restore(); }\n      else if(k<30){ ctx.globalAlpha=Math.max(0,1-(k-14)/16); const s=D.im==='freccia'?1.0:0.9; ctx.drawImage(im,D.x-im.width*s/2,GROUND-im.height*s*0.75,im.width*s,im.height*s); ctx.globalAlpha=1; } } }\n  const M=F.uw; if(M&&M.t>=12){ const im=ugoImg('burro'); if(im){ const s=1.0; ctx.translate(M.cx,GROUND+6); ctx.scale(M.dir,1); const wob=Math.sin(M.t*0.5)*4; ctx.drawImage(im,-im.width*s/2,-im.height*s+wob,im.width*s,im.height*s); } }\n  ctx.restore(); }\ntry{ EPICA.ugo=[\"Francese, banchiere, orgoglioso. Parla di finanza come di poesia e del Monte Bianco come di un torto da riparare.\", \"Quando evolve diventa Napoleone: formaggi in volo, cavalleria imperiale, bandiera al vento. Obiettivo dichiarato: riprendersi il Monte Bianco.\"]; Object.assign(COPPIAT,{\"ugo>stefano\": \"Ugo dice a SDB che sarebbe un buon francese. SDB lo prende come un complimento. Poi come un'offesa.\", \"stefano>ugo\": \"Il Monte Bianco \u00e8 italiano. SDB ha preparato una memoria di quaranta pagine.\", \"ugo>allibrator\": \"Finanza contro scommesse. In fondo fanno lo stesso mestiere.\", \"allibrator>ugo\": \"L'Allibrator ha gi\u00e0 la quota. Ugo ha gi\u00e0 il formaggio.\"}); }catch(e){}\n";